import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"首次设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/setup.md","filePath":"zh/setup.md","lastUpdated":1792880859000}'),i={name:"zh/setup.md"};function n(s,e,h,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="首次设置" tabindex="-1">首次设置 <a class="header-anchor" href="#首次设置" aria-label="Permalink to &quot;首次设置&quot;">​</a></h1><p>本页介绍第一次启动 MeetCue 时打开的设置向导。整个过程约五分钟，大部分时间花在创建 API 密钥上。</p><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>你需要一个语音识别供应商账号和一个大模型供应商账号。MeetCue 不替你选：向导会把价格并排列出，由你决定。</p><table tabindex="0"><thead><tr><th>任务</th><th>本版本支持的供应商</th></tr></thead><tbody><tr><td>语音识别</td><td>Soniox、Deepgram</td></tr><tr><td>问题检测与要点生成</td><td>Anthropic、任意 OpenAI 兼容接口</td></tr></tbody></table><p>问题检测和要点生成可以用不同的模型，甚至不同的供应商。检测只需判断“是不是问题”，通常选便宜的模型就够了。</p><h2 id="第-1-步-语言" tabindex="-1">第 1 步：语言 <a class="header-anchor" href="#第-1-步-语言" aria-label="Permalink to &quot;第 1 步：语言&quot;">​</a></h2><p>选择 <strong>English</strong> 或 <strong>简体中文</strong>，也可以跟随 Windows 显示语言。之后可在 <strong>设置 › 通用</strong> 中修改，所有窗口即时切换。</p><h2 id="第-2-步-音频" tabindex="-1">第 2 步：音频 <a class="header-anchor" href="#第-2-步-音频" aria-label="Permalink to &quot;第 2 步：音频&quot;">​</a></h2><p>MeetCue 同时听两路声音：</p><ul><li><strong>麦克风（我）</strong>：你说话用的麦克风。“系统默认”跟随 Windows 声音设置里选的设备。</li><li><strong>与会者声音</strong>：默认播放设备里播放的所有声音，会议软件就是从这里播放其他人的声音。</li></ul><p>点击 <strong>测试电平</strong>，播放一段视频并说几句话，两个电平条都应跳动。如果系统声音一直没有电平，请看<a href="/meetcue/zh/troubleshooting/audio">音频与设备</a>。</p><div class="tip custom-block"><p class="custom-block-title">建议戴耳机</p><p>使用外放时，麦克风也会录到与会者的声音。MeetCue 能过滤大部分回声，但戴耳机效果最好。</p></div><h2 id="第-3-步-模型与价格" tabindex="-1">第 3 步：模型与价格 <a class="header-anchor" href="#第-3-步-模型与价格" aria-label="Permalink to &quot;第 3 步：模型与价格&quot;">​</a></h2><p>为三项任务各选一个模型。每行显示该模型的单价（每音频小时，或每百万输入、输出 token）、每小时会议的预计费用，以及运行延迟探测后的实测延迟。列表按预计费用排序，<strong>最省</strong> 和 <strong>最快</strong> 标出最优的一项。每一项都由你亲自选择，三项都选好后才能继续。</p><p>MeetCue 不内置价格。打开模型列表时，它会直接读取各供应商官网的价格页（Anthropic、Soniox、Deepgram），以及在模型列表中附带价格的 OpenAI 兼容接口。官网未覆盖的部分取自<a href="/meetcue/zh/reference/pricing">价格参考</a>，最近一次的价格会保留供离线使用；点 <strong>更新价格</strong> 可重新读取。只有在任何来源都没有价格的模型，才会改为链接到供应商的价格页。</p><h2 id="第-4-步-api-密钥" tabindex="-1">第 4 步：API 密钥 <a class="header-anchor" href="#第-4-步-api-密钥" aria-label="Permalink to &quot;第 4 步：API 密钥&quot;">​</a></h2><p>为每个选中的供应商粘贴密钥，点击 <strong>保存并验证</strong>。密钥只保存在 Windows 凭据管理器中，不会出现在配置文件或日志里。</p><p>各家密钥的获取方法见<a href="/meetcue/zh/guide/providers">供应商配置</a>：</p><ul><li><a href="/meetcue/zh/guide/providers#soniox">Soniox</a></li><li><a href="/meetcue/zh/guide/providers#deepgram">Deepgram</a></li><li><a href="/meetcue/zh/guide/providers#anthropic">Anthropic</a></li><li><a href="/meetcue/zh/guide/providers#openai-compatible-apis">OpenAI 兼容接口</a></li></ul><p>验证失败时，提示里会带错误码，例如 <a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>。点击 <strong>查看解决办法</strong> 可直接打开对应说明。</p><h2 id="第-5-步-延迟探测" tabindex="-1">第 5 步：延迟探测 <a class="header-anchor" href="#第-5-步-延迟探测" aria-label="Permalink to &quot;第 5 步：延迟探测&quot;">​</a></h2><p>探测会测量从你的网络访问各供应商的速度，并为每家选出最快的端点。有密钥时花费几美分；只测网络则完全免费。可以先跳过，之后在 <strong>设置 › 供应商与费用</strong> 中运行。参见<a href="/meetcue/zh/guide/latency">延迟探测</a>。</p><h2 id="第-6-步-完成" tabindex="-1">第 6 步：完成 <a class="header-anchor" href="#第-6-步-完成" aria-label="Permalink to &quot;第 6 步：完成&quot;">​</a></h2><p>下次会议开始时按 <code>Ctrl+Alt+Space</code>。想先看看效果，可以试试<a href="/meetcue/zh/quick-start">五分钟上手</a>。</p>',25)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
